print('accepted arrows:',len(links), Counter(l['mode'] for l in links.values()), Counter(l.get('shape') for l in links.values()))
print('claims:',len(props), Counter(props.values()))
print('sustain source kinds:', Counter(props.get(s,'?') for (s,t),l in links.items() if l['mode']=='sustain'))
"

